android.extraProguardRules:
# R8 keep rules. These live here rather than in android/app/proguard-rules.pro
# because android/ is gitignored and regenerated by prebuild on every EAS build,
# so anything written there survives locally and vanishes in the cloud.

# React Native core - native modules and view managers are resolved by name
# from JavaScript, which R8 cannot see.
-keep class com.facebook.react.** { *; }
-keep class com.facebook.jni.** { *; }
-keepclassmembers class * { @com.facebook.react.uimanager.annotations.ReactProp <methods>; }
-keepclassmembers class * { @com.facebook.react.bridge.ReactMethod <methods>; }
-keep @com.facebook.proguard.annotations.DoNotStrip class *
-keepclassmembers class * { @com.facebook.proguard.annotations.DoNotStrip *; }

# Hermes
-keep class com.facebook.hermes.** { *; }
-keep class com.facebook.jsi.** { *; }

# Reanimated
-keep class com.swmansion.reanimated.** { *; }
-keep class com.facebook.react.turbomodule.** { *; }

# Expo modules, discovered by reflection from a generated registry
-keep class expo.modules.** { *; }
-keep class expo.core.** { *; }

# Sentry - stack traces are the product; renaming its internals makes every
# report harder to read exactly when reports matter.
-keep class io.sentry.** { *; }
-dontwarn io.sentry.**

# RevenueCat - subscription state is parsed into model classes by name
-keep class com.revenuecat.purchases.** { *; }

# Google Mobile Ads
-keep class com.google.android.gms.ads.** { *; }
-dontwarn com.google.android.gms.**

# Noisy optional dependencies
-dontwarn okhttp3.**
-dontwarn okio.**
-dontwarn javax.annotation.**

# Without these a release crash reports as Unknown Source and Sentry stops
# being worth having.
-keepattributes SourceFile,LineNumberTable
-renamesourcefileattribute SourceFile
